import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Plateaus","description":"","frontmatter":{"title":"Plateaus","covers":{"screens":["SCR-065","SCR-066"],"stories":["US-084","US-085","US-086","US-087","US-088","US-089","US-155","US-157"]}},"headers":[],"relativePath":"de/usage/plateaus.md","filePath":"de/usage/plateaus.md"}`),a={name:`de/usage/plateaus.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="plateaus" tabindex="-1">Plateaus <a class="header-anchor" href="#plateaus" aria-label="Permalink to “Plateaus”">​</a></h1><p>Ein Plateau ist ein benannter, stabiler Zustand deiner Architektur. Die <strong>Baseline</strong> ist die Architektur, die heute im Betrieb ist. <strong>Ziel-</strong> und <strong>Übergangsplateaus</strong> beschreiben geplante Zustände: einen Zielzustand und Zwischenstände auf dem Weg dorthin. <a href="./solutions">Lösungen</a> können auf ein Plateau hinarbeiten.</p><p>Für den Plateaumodus gibt es keinen Schalter: Er beginnt, wenn du die erste Baseline anlegst. Lösungen ohne Plateau arbeiten weiter wie bisher.</p><p>Zum Anlegen und Bearbeiten von Plateaus brauchst du die Berechtigung <code>plateau:write</code> (zum Beispiel die Rolle <code>enterprise-architect</code>). Um sie zu sehen, reicht <code>plateau:write</code>, <code>plateau:go-live</code> oder <code>solution:write</code> (siehe <a href="./../administration/roles-and-permissions">Rollen und Berechtigungen</a>).</p><h2 id="die-seite-plateaus" tabindex="-1">Die Seite Plateaus <a class="header-anchor" href="#die-seite-plateaus" aria-label="Permalink to “Die Seite Plateaus”">​</a></h2><p>Wähle in der Kopfzeile <em>Plateaus</em>. Die Seite zeigt:</p><ul><li>die <strong>Baseline</strong>, hervorgehoben, mit dem Datum, seit dem sie gilt;</li><li>die <strong>Ziel- und Übergangsplateaus</strong>, nach geplantem Datum, jeweils mit Vorgänger, Basis und der Zahl der Lösungen, die darauf hinarbeiten. Gibt es keines, steht dort „Noch kein Zielplateau geplant“;</li><li>die <strong>realisierten Plateaus</strong>, eingeklappt, das neueste zuerst. Ein Plateau wird realisiert, wenn sein Nachfolger live geht.</li></ul><h2 id="die-initiale-baseline-anlegen" tabindex="-1">Die initiale Baseline anlegen <a class="header-anchor" href="#die-initiale-baseline-anlegen" aria-label="Permalink to “Die initiale Baseline anlegen”">​</a></h2><p>Ohne Baseline steht auf der Seite „Es gibt noch kein Baseline-Plateau“. Wähle <em>Initiale Baseline anlegen</em>, gib einen Namen wie „Baseline 2026-Q2“ und optional eine Beschreibung und das Datum des Stands ein und wähle <em>Plateau anlegen</em>. Es gibt immer nur eine Baseline.</p><h2 id="ein-ziel-oder-ubergangsplateau-anlegen" tabindex="-1">Ein Ziel- oder Übergangsplateau anlegen <a class="header-anchor" href="#ein-ziel-oder-ubergangsplateau-anlegen" aria-label="Permalink to “Ein Ziel- oder Übergangsplateau anlegen”">​</a></h2><ol><li><p>Wähle <em>Neues Plateau</em>.</p></li><li><p>Fülle den Dialog aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>Pflicht, bis 255 Zeichen, eindeutig unabhängig von Gross- und Kleinschreibung</td></tr><tr><td>Art</td><td><em>Ziel</em> oder <em>Übergang</em></td></tr><tr><td>Beschreibung</td><td>optional, bis 2000 Zeichen</td></tr><tr><td>Gültig ab</td><td>optional: das geplante Go-live-Datum</td></tr><tr><td>Vorgänger</td><td>das Plateau, auf das dieses folgt; die Baseline ist vorausgewählt. Ein realisiertes Plateau kann kein Vorgänger sein</td></tr><tr><td>Basis</td><td>wovon die Lösungen dieses Plateaus ausgehen (siehe unten)</td></tr></tbody></table></li><li><p>Wähle <em>Plateau anlegen</em>.</p></li></ol><h3 id="basis" tabindex="-1">Die Basis <a class="header-anchor" href="#basis" aria-label="Permalink to “Die Basis”">​</a></h3><p>Die Basis bestimmt, was eine Lösung, die auf das Plateau hinarbeitet, als ihre Ausgangslage sieht:</p><ul><li><strong>Aktueller Katalog:</strong> der Katalog, wie er jetzt ist.</li><li><strong>Inhalt des Vorgängers:</strong> das Vorgängerplateau mit den Änderungen seiner aktiven Lösungen. Eine Entität, die eine Lösung des Vorgängers ausser Betrieb nimmt, ist mit <em>Wird abgelöst durch …</em> markiert, eine neue Entität, die sie vorschlägt, mit <em>Vorgeschlagen von …</em>, und geänderte Namen und Werte zeigen ihren geplanten Wert. Eine vorgeschlagene Entität kann noch nicht geändert oder ausser Betrieb genommen werden, weil sie vor ihrem Go-live nicht existiert. Hat der Vorgänger selbst die Basis „Inhalt des Vorgängers“, zählt auch dessen Vorgänger.</li></ul><p>Ändern zwei Lösungen desselben Plateaus dasselbe Feld, zählt die zuletzt gemachte Änderung.</p><h2 id="ein-plateau-bearbeiten" tabindex="-1">Ein Plateau bearbeiten <a class="header-anchor" href="#ein-plateau-bearbeiten" aria-label="Permalink to “Ein Plateau bearbeiten”">​</a></h2><p>Wähle <em>Bearbeiten</em> neben einem Plateau, um Name, Beschreibung, Datum, Vorgänger oder Basis zu ändern. Die Art ändert sich nur durch das Go-live. Der Vorgänger ist fest, sobald eine Lösung auf das Plateau hinarbeitet.</p><p>Ein realisiertes Plateau ist schreibgeschützt: Es hat kein <em>Bearbeiten</em>, und die API antwortet „Realized plateau is read-only“.</p><h2 id="go-live" tabindex="-1">Ein Plateau live schalten <a class="header-anchor" href="#go-live" aria-label="Permalink to “Ein Plateau live schalten”">​</a></h2><p>Ist der geplante Zustand erreicht, geht das Plateau live: Es wird die neue Baseline, die alte Baseline wird realisiert, und die Änderungen seiner Lösungen kommen in den Katalog. Du brauchst die Berechtigung <code>plateau:go-live</code> (zum Beispiel die Rolle <code>enterprise-architect</code>).</p><p>Nur das Plateau, das direkt auf die Baseline folgt, kann live gehen; es zeigt <em>Live schalten</em>. Der Dialog <em>Plateau live schalten</em> zeigt:</p><ul><li>welches Plateau die Baseline wird und welches realisiert wird;</li><li>wie viele Entitäten angelegt, geändert und abgelöst werden;</li><li>die Lösungen, die mit dem Plateau live gehen;</li><li>Warnungen, die das Go-live nicht stoppen: noch nicht genehmigte Lösungen und die offenen Punkte, die das Go-live hinterlässt.</li></ul><p>Gib den genauen Namen des Plateaus ein und wähle <em>Go-live bestätigen</em>. Das Go-live kann nicht rückgängig gemacht werden.</p><p>Alle aktiven Lösungen des Plateaus gehen in einem Schritt live, in der Reihenfolge, in der ihre Änderungen zuletzt bearbeitet wurden, jede so, wie eine einzelne <a href="./solutions#go-live">Lösung live geht</a>. Wurde ein Feld, das eine Lösung ändert, inzwischen geändert, im Katalog oder durch eine Lösung, die vor ihr live geht, listet der Dialog den Konflikt bei dieser Lösung; <em>Auflösen</em> öffnet <em>Konflikte auflösen</em>. Solange nicht jeder Konflikt aufgelöst ist, geht nichts live. Auch eine Änderung einer Entität, die aus dem Repository gelöscht wurde, hält das Go-live auf: Der Dialog listet sie bei ihrer Lösung, und die Lösung muss die Änderung entfernen oder die Entität muss zuerst wiederhergestellt werden. Schlägt beim Go-live etwas fehl, ändert sich nichts.</p><p>Nach dem Go-live:</p><ul><li>ist das Plateau ab heute die Baseline, und die alte Baseline ist bis heute realisiert und schreibgeschützt;</li><li>sind die Lösungen des Plateaus <em>Umgesetzt</em>, und abgelöste Entitäten sind aus dem Katalog gelöscht;</li><li>folgen Plateaus, die auf die alte Baseline folgten, nun der neuen, und ihre Lösungen starten von ihr.</li></ul><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><p><code>GET /api/v1/plateaus</code> listet die Plateaus, <code>POST /api/v1/plateaus</code> legt eines an, und <code>GET</code> und <code>PUT /api/v1/plateaus/{id}</code> lesen und bearbeiten eines. <code>GET /api/v1/plateaus/{id}/go-live</code> zeigt, was das Go-live tun würde, und <code>POST</code> mit dem Namen des Plateaus schaltet es live. Anlegen, Bearbeiten und Go-live werden als <code>plateau.created</code>, <code>plateau.updated</code> und <code>plateau.went-live</code> protokolliert.</p>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};